    표5_매튜헨리: [
        {"영어원문":"The same judgment of fire falls upon Tyre as upon Gaza—for though their specific sins differ, both violated God's moral order.", "한국어번역":"가사에 임한 것과 동일한 불의 심판이 두로에도 임한다. 구체적인 죄는 달라도 둘 다 하나님의 도덕 질서를 위반했기 때문이다.", "핵심통찰":"죄의 형태는 다를지라도 하나님의 심판 원리는 동일하다"},
        {"영어원문":"Tyre's magnificent palaces, built by wealth from commerce, shall be consumed—no earthly treasure can outlast divine judgment.", "한국어번역":"무역의 부로 쌓은 두로의 화려한 궁궐들이 소멸될 것이다. 어떤 세상의 보물도 하나님의 심판을 견딜 수 없다.", "핵심통찰":"세상의 보물은 영원하지 않다"},
        {"영어원문":"God's repeated warnings through multiple prophets gave Tyre ample opportunity to repent, making judgment all the more deserved.", "한국어번역":"여러 선지자들을 통한 하나님의 반복된 경고는 두로에게 충분한 회개의 기회를 주었으므로 심판이 더욱 마땅했다.", "핵심통찰":"반복된 경고를 무시하는 것은 더 큰 죄책을 쌓는 것이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"두로의 불타는 궁궐 - 아무리 강해도 하나님의 공의는 반드시 온다", "예화_적용":"알렉산더 대왕에 의한 두로의 멸망은 하나님의 예언 성취의 대표적 사례다"},
        {"대지":"서론", "내용":"두로. 고대 세계 최대의 무역 도시. 바다 위 섬에 세워진 천혜의 요새. 수백 년간 어떤 군대도 정복하지 못했다. 하지만 하나님은 그 궁궐들을 불사르겠다고 선언하셨다.", "예화_적용":"인간의 가장 위대한 업적도 하나님의 심판 앞에서는 덧없다"},
        {"대지":"1대지: 두로성에 불을 (구체적 심판)", "내용":"추상적이 아닌 특정 도시 두로에 대한 구체적 심판 선언. 하나님의 공의는 역사의 특정 시간과 장소에서 실현된다.", "예화_적용":"하나님의 약속과 심판은 구체적인 역사 현실에서 이루어진다"},
        {"대지":"2대지: 궁궐들을 사르리라 (번영의 소멸)", "내용":"무역과 부로 쌓은 화려한 궁궐들이 불에 탄다. 불의한 방법으로 쌓은 부는 영원하지 않다.", "예화_적용":"하나님이 허락하지 않으신 방법으로 쌓은 것은 반드시 대가를 치른다"},
        {"대지":"3대지: 반복되는 패턴 (심판의 보편성)", "내용":"다메섹, 가사, 두로... 동일한 패턴의 반복. 하나님의 공의는 지역과 민족을 가리지 않는다.", "예화_적용":"하나님의 도덕 기준은 나라와 문화를 초월하여 모든 인류에게 동일하게 적용된다"},
        {"대지":"결론", "내용":"두로의 역사는 하나님의 예언의 신뢰성과 공의의 확실성을 증명한다. 오늘 우리 시대에도 하나님의 공의는 작동하고 있다. 역사 앞에 겸손하고 하나님을 경외하며 살자.", "예화_적용":"하나님의 말씀 앞에 겸손히 서서 나의 삶을 돌아보자"}
    ],
