    표8_상담적용: [
        {"상황":"자연재해나 역사적 재앙으로 하나님에 대한 의심이 생긴 분", "성경원리":"하나님은 전쟁과 폭풍 모두를 사용하시는 역사와 자연의 주권자이시다. 재앙이 하나님의 부재를 증명하는 것이 아니라 그분의 주권을 보여준다.", "실제적용":"고통과 재앙 앞에서 하나님을 의심하기보다 신뢰를 선택하라. 욥의 예처럼 고통 속에서도 하나님께 솔직하게 나아가라"},
        {"상황":"권력이나 지위를 남용하는 분", "성경원리":"랍바 수도도 하나님의 심판을 피하지 못했다. 권력의 중심에 있는 자들이 더 큰 책임을 진다.", "실제적용":"주어진 권한과 지위를 하나님 앞에서 어떻게 사용하는지 점검하라. 권력은 섬기기 위한 것이지 착취하기 위한 것이 아니다"},
        {"상황":"역사의 혼란 속에서 방향을 잃은 분", "성경원리":"역사의 전쟁과 자연의 폭풍이 하나님의 섭리 안에 있다. 하나님은 혼란 속에서도 역사를 주관하신다.", "실제적용":"혼란스러운 상황에서 하나님의 말씀으로 돌아가라. 역사의 방향은 하나님이 결정하신다"}
    ],
