        {"구절":"롬 1:18-20", "연결점":"이방인도 하나님의 진노 아래 있음", "구분":"신약"},
        {"구절":"마 25:32", "연결점":"모든 민족이 주 앞에 모여 심판받음", "구분":"신약"},
        {"구절":"창 23:4-20", "연결점":"아브라함이 사라의 장지를 구함 - 죽은 자에 대한 존중", "구분":"구약"}
