        {"구절":"신 32:35-36", "연결점":"원수 갚음이 내게 있고 보응이 나에게 있음", "구분":"구약"},
        {"구절":"계 20:11-15", "연결점":"흰 보좌 심판 - 최후의 하나님 법정", "구분":"신약"}
