        {"새찬송가":"559", "통일찬송가":"428", "제목":"내 죄를 회개하고", "선정이유":"위선적 예배를 회개하는 찬송"},
        {"새찬송가":"46", "통일찬송가":"50", "제목":"만세반석 열리니", "선정이유":"진정한 피난처와 구원자이신 하나님"}
