    본문내용: "또 추수하기 석 달 전에 내가 너희에게 비를 그쳐서 어떤 성읍에는 비를 내리고 어떤 성읍에는 비를 내리지 아니하여 땅 한 부분은 비를 얻고 비 없는 다른 부분은 말랐으며",
